/* Types */
/**  What a Human action left: its notice and the request as it now stands. */
export type Acted = {
	notice: Notice,
	view: HumanView | null,
};

export type Attention = {
	mark: Mark,
	text: string,
};

/**
 *  A branch by value, so a selection survives refreshes that reorder the pane. Paths are
 *  round-trip; names for people come with the branch.
 */
export type BranchKey = 
/**  A Git repository's branch, by the repository's common directory. */
{ kind: "branch"; common: PathKey; 
/**  Refused at the boundary unless a branch name. */
branch: string } | 
/**  A detached Git worktree, by its folder. */
{ kind: "detached"; common: PathKey; path: PathKey } | 
/**  A folder outside Git. */
{ kind: "folder"; path: PathKey };

/**  One live branch of the pane: `project / branch`, then its timeline, newest first. */
export type BranchView = {
	key: BranchKey,
	project: string,
	/**  The branch, a detached worktree's folder, or empty for a folder outside Git. */
	name: string,
	/**  Where its Current is scanned and its tools run. */
	workspace: PathKey,
	/**  Its timeline: its newest Runs, newest first, led by the one in progress or else the Current. */
	chips: Chip[],
	/**  Older Runs than the timeline holds exist: **Older runs** at its end shows them. */
	older: boolean,
	/**  Starred: listed before the branches that are not. */
	starred: boolean,
};

export type BrowseView = {
	query: QueryView,
	/**  The branches the search keeps, in its order. */
	branches: BranchView[],
	/**  The waiting Human reviews the search keeps, newest first. */
	waiting: WaitingRow[],
	/**  The branch of the folder the app was started for. */
	launch: BranchKey | null,
	/**  The shown Run, once read. */
	run: RunPanel | null,
	/**  The shown Run no longer exists or cannot be read. */
	missing: boolean,
	/**  What went wrong: a failed read, Run records that cannot be read. */
	notice: string | null,
	/**  False until the first snapshot was read. */
	refreshed: boolean,
	/**  The state was replaced since the last view: Details and drafts no longer apply. */
	replaced: boolean,
	/**
	 *  Grows with every change of the shown snapshot; a response with a lower revision is
	 *  older than one already shown, and views derived from the snapshot (Detail) read again
	 *  when it grows.
	 */
	revision: number,
};

/**  An eval at a glance, from the library's [`monitor::Card`]. */
export type CardView = {
	instruction: string,
	/**  `None` until the eval has a result. */
	result: ResultEntry[] | null,
	exitCode: number | null,
	error: string | null,
	reused: boolean,
	took: string | null,
	tokens: number | null,
	model: string | null,
};

/**  One entry of a branch's timeline: a Run, or the branch's Current. */
export type Chip = { kind: "run"; id: string; mark: Mark; 
/**  Its status in words: `GREEN`, `RED`, `Running`, `Waiting for sign-off`. */
status: string; 
/**  How long ago it started, `25m ago`; an open one's time so far, `2m 22s`. */
age: string; running: boolean; 
/**  What its requester said it is working on (`verify --comment`). */
comment: string | null } | 
/**  The worktree as it is now. */
{ kind: "current" };

export type Claimant = {
	reviewer: string,
	mine: boolean,
};

/**
 *  What the sign-in asks for: open `url`; `callback` says whether the browser can return
 *  here (when the port is taken, only pasting the redirect URL finishes it).
 */
export type CodexPrompt = {
	url: string,
	callback: boolean,
	/**  The sign-in to wait for with [`codex_login_wait`]. */
	signIn: SignInId,
};

/**  How Codex is signed in, read offline as the CLI does. */
export type CodexStatus = 
/**  Not signed in. */
{ state: "absent" } | 
/**  artifactize's own sign-in. */
{ state: "stored"; expiry: Expiry } | 
/**  A read-only Codex auth file from ARTIFACTIZE_CODEX_AUTH_FILE; never written here. */
{ state: "file"; path: string; expiry: FileExpiry } | 
/**  Tokens cannot be stored where this state lives, and why. */
{ state: "refused"; reason: string };

/**  The completion of a search's last term. */
export type Completion = {
	/**  The search before the completed term; a candidate replaces the rest. */
	keep: string,
	candidates: string[],
};

/**  What asking the store answered. */
export type Connection = 
/**  The token was accepted. */
{ state: "signedIn"; principal: string; scopes: string[] } | 
/**  The store answered, but not with an accepted token. */
{ state: "refused"; error: string } | 
/**  The store sent no HTTP response. */
{ state: "unreachable"; error: string };

/**  The shown Current of `branch` changed: a scan published a step, or ended. */
export type CurrentChanged = {
	branch: BranchKey,
};

/**  A branch's Current as the Main area shows it; its structure text is read on its own. */
export type CurrentView = {
	branch: BranchKey,
	/**  When this step was scanned, at milliseconds since the Unix epoch. */
	scannedAt: number | null,
	fingerprint: string,
	/**  Grows with each step: the graph and an open Detail read again when it does. */
	revision: ScanId,
	/**  The branch's scan is still running. */
	scanning: boolean,
	/**  How many Artifacts are still being checked, of how many. */
	checking: number,
	artifacts: number,
	/**  Why the branch's last scan failed; what it published before stays shown. */
	failure: string | null,
};

export type CustomProvider = {
	name: string,
	target: Target,
};

/**  What a Detail describes, from the library's [`Target`]. */
export type DetailTarget = "run" | "artifact" | "eval";

export type DetailView = {
	source: Source,
	node: string,
	target: DetailTarget,
	title: string,
	/**  One-line outcome: state, elapsed time, profile and dependencies. */
	summary: string,
	/**  The eval's request, when it has one in this Run. */
	request: string | null,
	profile: Profile | null,
	mark: Mark | null,
	/**  On a Current, in place of a status: what verify would do. */
	plan: PlanLine | null,
	/**  Outcome → Waits for → What → Provenance → Technical; empty sections are left out. */
	sections: SectionView[],
	/**  Saved runtime stdout/stderr, or why there are none. */
	evidence: Evidence | null,
	/**  An eval's status line, instruction and result; `None` for an Artifact or the Run. */
	card: CardView | null,
	/**  A running request: its Detail follows live changes. */
	running: boolean,
};

/**  The frontend's draft of one verdict: field values by name. */
export type Draft = {
	verdict: Verdict,
	fields: ([string, FieldValue])[],
};

/**  The API a custom endpoint speaks. */
export type EndpointApi = "openaiResponses" | "openaiChat" | "anthropic" | "gemini";

export type Evidence = {
	title: string,
	text: string,
};

/**  How long a stored sign-in's access token lasts. */
export type Expiry = 
/**  It still works. */
{ state: "usable"; expiresAt: UnixSeconds } | 
/**  It ran out; it refreshes on use unless the refresh token was revoked. */
{ state: "expired"; expiresAt: UnixSeconds };

export type Failure = 
/**  Reading the state failed; the last snapshot stays on screen. */
{ kind: "read"; message: string } | 
/**  A Human action was refused or failed; nothing was decided. */
{ kind: "action"; message: string } | 
/**  Owner fields are not a valid result yet; the request stays waiting and correctable. */
{ kind: "invalid"; message: string } | 
/**  What the call names is not loaded or no longer exists. */
{ kind: "missing"; message: string } | 
/**  A sign-in, sign-out, listing or store call failed, with the CLI's own message. */
{ kind: "account"; message: string } | 
/**  Reading or saving a machine-wide setting failed, with the CLI's own message. */
{ kind: "setting"; message: string };

export type Field = {
	key: string,
	value: string,
};

/**  How one owner field is entered. */
export type FieldInput = 
/**  A `const`: filled in and fixed; `value` is its JSON. */
{ kind: "fixed"; value: string } | { kind: "bool" } | 
/**  String `enum` options, as their JSON text. */
{ kind: "choice"; options: string[] } | { kind: "text" } | { kind: "integer" } | { kind: "number" } | 
/**  An array of strings, entered one item at a time. */
{ kind: "list" } | 
/**  An array of flat objects: a group of these fields per item. */
{ kind: "groups"; fields: FormField[] };

/**  A field's draft value, by the field's kind. */
export type FieldValue = { kind: "fixed" } | { kind: "bool"; value: boolean | null } | 
/**  The chosen option's index. */
{ kind: "choice"; value: number | null } | { kind: "text"; value: string } | { kind: "integer"; value: string } | { kind: "number"; value: string } | { kind: "list"; value: string[] } | 
/**  Each group's field values by name. */
{ kind: "groups"; value: (([string, FieldValue])[])[] };

/**  What a read-only Codex auth file says of its token. */
export type FileExpiry = { state: "usable"; expiresAt: UnixSeconds | null } | { state: "expired" };

export type FormField = {
	name: string,
	required: boolean,
	/**  The type and constraints, then any description. */
	hint: string,
	input: FieldInput,
};

/**  A new form: its typed fields, with the draft the library starts it from. */
export type FormView = {
	verdict: Verdict,
	fields: FormField[],
	draft: Draft,
};

export type Graph = {
	source: Source,
	/**  Names the graph's Artifacts and edges, whatever their lights. */
	shape: ShapeKey,
	update: Update,
};

/**  `target`'s evals depend on `source`; both are tree ids. */
export type GraphEdge = {
	source: string,
	target: string,
	light: Light,
};

export type GraphNode = {
	/**  The Artifact row's tree id, `a:<artifact>`. */
	id: string,
	name: string,
	/**  The space of a `space::name`, which the graph draws its Artifacts together in. */
	space: string | null,
	/**  What the node shows: the name without its space. */
	label: string,
	light: Light,
	/**  Under the name: on a Current what verify would do, `would run (2 evals)`. */
	note: string | null,
};

/**  The Tool logs that changed, each whole. */
export type HumanToolLog = {
	logs: KeyedLog[],
};

/**  One request in the shared Human Detail. */
export type HumanView = {
	/**  The request every action goes to: a waiting follower's original. */
	id: string,
	title: string,
	/**  The Artifact the reviewed eval belongs to: its tools come first. */
	artifact: string,
	/**  Status, claim and waiting time in one line. */
	meta: string,
	/**  For a follower: which request and repository its actions go to. */
	shared: string | null,
	instruction: string,
	/**  Identifiers, the repository, the claim and the raw owner schemas. */
	technical: Field[],
	mark: Mark,
	stage: Stage,
	claim: Claimant | null,
	reviewer: string,
	tools: ToolView[],
	/**  A Human definition is recorded; without one, tools and schemas are unknown. */
	recorded: boolean,
	/**  A completed request's status and result, or its error. */
	result: string | null,
	/**  The state generation it was read from; a newer one means it no longer applies. */
	generation: number,
};

/**  A cancellable job of one Human action, numbered by the frontend. */
export type JobId = number;

/**  What saving a custom endpoint does with its key. */
export type KeyInput = 
/**  Save this key; it is never returned. */
{ kind: "set"; key: string } | 
/**  Keep the key the endpoint already has. */
{ kind: "keep" } | 
/**  No key. */
{ kind: "none" };

/**  Where a built-in provider's key comes from; never its value. */
export type KeySource = 
/**  Its environment variable, which is used first. */
"environment" | 
/**  Saved in Settings or with `artifactize login`. */
"saved" | "absent";

export type KeyStatus = {
	provider: Provider,
	/**  The environment variable read first. */
	variable: string,
	source: KeySource,
	/**  Whether a key is saved here, also while the variable comes first. */
	saved: boolean,
};

/**  One Tool log: one entry per run, in the order they started. */
export type KeyedLog = {
	key: LogKey,
	entries: LogEntry[],
};

/**  What the frontend needs to know about this launch. */
export type LaunchView = {
	mode: Mode,
	state: string,
	reviewer: string,
	request: string | null,
};

/**  How a node or edge is lit, in precedence order; the frontend maps each to one colour. */
export type Light = 
/**  An eval's verdict is RED. */
"red" | 
/**  An eval failed operationally: ERROR. */
"error" | 
/**  Running, or waiting for its Human. */
"active" | 
/**  Cannot proceed: an upstream Artifact is RED, ERROR or itself blocked. */
"blocked" | 
/**  Runnable but still waiting: queued, or for upstream Artifacts not done yet. */
"waiting" | 
/**  Every eval is GREEN. */
"green" | 
/**  On a Current: at least one eval would run. */
"run" | 
/**  On a Current: every eval's result would be reused. */
"reused" | 
/**  On a Current: what would happen is still being checked. */
"checking";

/**
 *  One tool run: its start line's facts, what it printed as it ran, and its end line once it
 *  ended. A launched program's lines keep arriving after its tool returned.
 */
export type LogEntry = {
	/**  The run, unique while the app runs. */
	run: string,
	/**  Its start, at milliseconds since the Unix epoch. */
	at: number | null,
	operation: string,
	artifact: string,
	lines: LogText[],
	/**  The run's end line, `■ exit 0` or how it ended. */
	end: LogText | null,
};

/**  Whose Tool log it is: a review's, or an Artifact's in a worktree. */
export type LogKey = { kind: "review"; request: string } | { kind: "artifact"; workspace: PathKey; artifact: string };

/**  One line of a run: what it printed, red when it went to stderr or the run failed. */
export type LogText = {
	text: string,
	error: boolean,
};

/**  A status with its glyph, as badges, headlines and counts show it. */
export type Mark = {
	status: Status,
	glyph: string,
};

/**  What the Main area opens on; everything else stays reachable from the Pane. */
export type Mode = 
/**  The branch of `--repo` with its last chip, or nothing chosen. */
"monitor" | 
/**  A waiting Human review: the one named, else the newest. */
"review" | 
/**  The Current of the branch of `--repo`. */
"graph";

export type Model = {
	slug: string,
	displayName: string,
};

export type Movement = { kind: "up"; rows: number } | { kind: "down"; rows: number } | { kind: "top" } | { kind: "bottom" };

/**  A step of the pane and how to read the state for it. */
export type Navigate = {
	/**  Which Run the Main area shows after this step. */
	run: RunStep,
	/**  The pane's search, when it changed. */
	query: string | null,
	/**  Reach further back in this branch's Runs. */
	older: BranchKey | null,
	/**  Star a branch, or take its star away: starred branches are listed first. */
	star: Star | null,
	/**  Read the waiting reviews again: refreshes and change hints; navigation reuses them. */
	full: boolean,
	/**  Read everything again, after a resync hint or a manual refresh. */
	resync: boolean,
};

/**
 *  An Artifact between its neighbours, at most [`NEAR`] on each side: those shown first are the
 *  ones lit first in [`Light`]'s precedence (failing before passing), then in the tree's order.
 */
export type Neighbours = {
	/**  The Artifact, the neighbours shown, and the edges between it and them. */
	shape: Shape,
	/**  Artifacts its evals use beyond those shown. */
	moreUses: number,
	/**  Artifacts whose evals use it beyond those shown. */
	moreUsedBy: number,
};

export type NodeKind = "run" | "artifact" | "eval";

export type Notice = {
	text: string,
	error: boolean,
};

/**  The session behind a request, or why there is none to read. */
export type Opened = { kind: "local"; handle: TranscriptHandle; 
/**  The session id, which change hints name. */
session: string } | 
/**  Why the conversation cannot be shown. */
{ kind: "unavailable"; text: string };

/**
 *  A path as the frontend holds it: text with `/` on every system, which `PathBuf` reads back
 *  on all of them. Only this type makes or reads one.
 */
export type PathKey = string;

/**  On a Current: what verify would do with the Artifact or eval, and why. */
export type PlanLine = {
	glyph: string,
	/**  `would run (2 evals)`, `reused`, `waiting` or `blocked`. */
	text: string,
	tone: Tone,
	reason: string,
};

export type Profile = "runtime" | "agent" | "human";

/**  A built-in provider, as the CLI names it. */
export type Provider = "codex" | "openai" | "anthropic" | "gemini";

/**  The providers of this machine. */
export type Providers = {
	keys: KeyStatus[],
	custom: CustomProvider[],
};

export type Pushed = {
	dryRun: boolean,
	pushed: number,
	existing: number,
	skipped: number,
};

/**  The pane's search as typed, and why it lists nothing when it cannot be read. */
export type QueryView = {
	text: string,
	error: string | null,
};

/**  A newer release and how to update to it. */
export type ReleaseNotice = {
	running: string,
	latest: string,
	update: ReleaseUpdate,
};

/**  How to update this install, as [`release::Update`]. */
export type ReleaseUpdate = 
/**  Run this command. */
{ kind: "command"; command: string } | 
/**  Download this file and install it by hand, with the command when there is one. */
{ kind: "download"; url: string; command: string | null } | 
/**  See the release page: how the app was installed is unknown. */
{ kind: "page"; url: string };

/**  The release lookup as the header shows it, and when to ask again. */
export type ReleaseView = {
	notice: ReleaseNotice | null,
	/**  Milliseconds until the app asks again ([`release::recheck_interval`]). */
	recheckMs: number,
};

/**  `remote status`: never the token. */
export type RemoteStatus = 
/**  No remote review store is configured. */
{ state: "unconfigured" } | { state: "configured"; url: string; share: Share; tokenSource: TokenSource; connection: Connection };

/**  One entry of an eval's result, the verdict left out: a text, or a list of findings. */
export type ResultEntry = { kind: "text"; key: string; text: string } | { kind: "items"; key: string; items: ResultItem[] };

/**  A finding: its rule and place as the head (`item · where`), then its other fields. */
export type ResultItem = {
	head: string | null,
	fields: Field[],
};

export type Row = {
	text: string,
	/**  A collapsed tool activity line; toggling it shows names, targets and states. */
	group: boolean,
	/**  Under the subdued Thinking label. */
	thinking: boolean,
};

/**
 *  The shown Run: its headline and what needs attention. Its rows come one at a time, as a
 *  Detail asks for them ([`row`]): a Run can hold tens of thousands.
 */
export type RunPanel = {
	id: string,
	/**  The Run's own row, whose Detail its headline opens. */
	node: string,
	mark: Mark,
	/**  Validation at Run end, counts, time and tokens. */
	headline: string,
	/**  What its requester said it is working on (`verify --comment`), in full. */
	comment: string | null,
	/**  Counts alone, for a narrow pane. */
	counts: string,
	attention: Attention[],
	/**  Attention lines beyond the shown ones. */
	more: number,
};

/**  What a step does to the Run shown in the Main area. */
export type RunStep = 
/**  Leave the shown Run as it is. */
{ kind: "keep" } | 
/**  Show this Run. */
{ kind: "open"; id: string } | 
/**  Show no Run: the Main area shows a Current, a review or Settings. */
{ kind: "close" };

/**
 *  A scan of a branch's Current, or a step it published, numbered by the backend: a later
 *  one has a higher number.
 */
export type ScanId = number;

export type SectionName = "outcome" | "waits" | "what" | "provenance" | "technical";

export type SectionView = {
	name: SectionName,
	title: string,
	fields: Field[],
	/**  The `Waits for` section's lines. */
	waits: WaitLine[],
};

export type Segment = {
	text: string,
	tone: Tone | null,
};

/**  An Agent session file grew; only its open transcript reads again. */
export type SessionChanged = {
	session: string,
};

/**  Where a submission's settled result stands. */
export type Settled = 
/**  Settled locally and, with a review store configured, published to it. */
"published" | 
/**
 *  Settled locally, but publishing it failed: the result stands and is never submitted
 *  again; the notice says what failed.
 */
"savedLocally";

/**  The Artifacts and the edges between them, each with its light. */
export type Shape = {
	/**  Upstream first, in the tree's order. */
	nodes: GraphNode[],
	edges: GraphEdge[],
};

/**
 *  A shape of the selected Run's graph, its Artifacts and edges whatever their lights,
 *  numbered by the backend as it reads one.
 */
export type ShapeKey = number;

export type Share = 
/**  Reduced records without argv, captured output, tool calls or paths. */
"summary" | 
/**  Also the saved execution as is. */
"full";

/**  A Codex sign-in in progress. */
export type SignInId = number;

export type SignedOut = {
	/**  The store confirmed the revocation; otherwise only the local tokens were removed. */
	revoked: boolean,
	status: CodexStatus,
};

/**  The idle grace in force, and the longest one accepted, in whole seconds. */
export type SignoffGrace = {
	seconds: number,
	maxSeconds: number,
};

/**  What a graph or Detail shows: a saved Run, or a branch's worktree as it is now. */
export type Source = { kind: "run"; run: string } | { kind: "current"; branch: BranchKey };

export type Stage = 
/**  Waiting and not claimed by this reviewer: read-only until claimed. */
"claim" | 
/**  Claimed by this reviewer. */
"review" | "completed";

/**  A branch starred, or its star taken away. */
export type Star = {
	branch: BranchKey,
	on: boolean,
};

/**  The state changed, or (`resync`) hints may have been missed: read it afresh. */
export type StateChanged = {
	resync: boolean,
};

/**  Every status the monitor shows, most urgent first. */
export type Status = "ERROR" | "RED" | "BLOCKED" | "RUNNING" | "WAITING_HUMAN" | "QUEUED" | "BUDGET_EXHAUSTED" | "WAIT_DEPENDENCY" | "WAIT" | "STALE" | "UNREVIEWED" | "INCOMPLETE" | "DEFERRED" | "PROVISIONAL" | "YELLOW" | "GREEN" | "BASIS";

/**  A settled submission: how it stands, its notice and the completed request. */
export type Submitted = {
	settled: Settled,
	notice: Notice,
	view: HumanView | null,
};

/**  What a custom provider reaches; an endpoint's key only as whether one is saved. */
export type Target = { kind: "alias"; provider: Provider } | { kind: "endpoint"; api: EndpointApi; url: string; key?: boolean };

export type TokenSource = 
/**  ARTIFACTIZE_REMOTE_TOKEN. */
"env" | 
/**  Saved by `remote login`. */
"file" | "none";

export type Tone = "green" | "red" | "error" | "running" | "human" | "queued" | "blocked" | "muted";

export type ToolKind = 
/**  Starts a program and returns at once. */
"launch" | 
/**  Waits and captures the output. */
"output";

export type ToolView = {
	name: string,
	/**  The Artifact that declares it, and its name there: `open` of `notes` is `open_notes`. */
	artifact: string,
	operation: string,
	kind: ToolKind,
	description: string,
	/**  What running it does: the resolved command line, or a builtin's action. */
	action: string,
	/**  Why the command could not be resolved; it is shown as declared. */
	error: string | null,
};

/**  An open transcript reader. */
export type TranscriptHandle = number;

export type TranscriptView = {
	rows: Row[],
	/**  Row position, bottom or history, following or paused. */
	indicator: string,
	/**  The first shown row and how many laid-out rows there are: the scrollbar's position. */
	top: number,
	total: number,
	status: string | null,
	following: boolean,
	/**  More indexing or layout is pending; ask again for the rest. */
	loading: boolean,
};

/**  One tree row with its children: the Run row, an Artifact or an eval. */
export type TreeNode = {
	/**  Stable tree id: `run:<id>`, `a:<artifact>` or `e:<eval>`. */
	id: string,
	kind: NodeKind,
	glyph: string,
	tone: Tone,
	weight: Weight,
	name: string,
	/**  Dim markers after the name: `↻ peer`, `[file]`. */
	marks: string,
	text: Segment[],
	/**  Elapsed time of an eval, `passed/total` of an Artifact. */
	right: string,
	/**  The derived state changed after the Run ended. */
	changed: boolean,
	/**  An Artifact whose evals are all done. */
	done: boolean,
	/**  An in-progress or failed eval. */
	attention: boolean,
	/**  An ERROR, RED or waiting Human eval. */
	urgent: boolean,
	/**  The Artifacts this row depends on, unmet first. */
	upstream: UpstreamMark[],
	children: TreeNode[],
};

/**
 *  A moment as the library counts it: whole seconds since 1970, as decimal text so no value of
 *  the library's range is rounded on the way to the frontend.
 */
export type UnixSeconds = string;

/**  What changed in a graph since the shape the caller holds. */
export type Update = 
/**  A shape the caller does not hold, all lit. */
{
	kind: "shape",
} & Shape | 
/**  The caller's shape, relit: one light per node and per edge, in its order. */
{ kind: "lights"; nodes: Light[]; edges: Light[] };

/**  The Artifacts a row depends on, with whether each is complete (dim) or unmet (bright). */
export type UpstreamMark = {
	/**  The Artifact row's tree id. */
	node: string,
	complete: boolean,
};

export type Verdict = "GREEN" | "RED";

/**  One `Waits for` line: an upstream Artifact, or (`pending`) one of its unfinished evals. */
export type WaitLine = {
	text: string,
	pending: boolean,
};

/**  One Human review waiting for a person. */
export type WaitingRow = {
	id: string,
	eval: string,
	title: string,
	mark: Mark,
	project: string,
	branch: string,
	/**  How long it waits. */
	age: string,
	/**  `-`, the claimant, or `name (you)`. */
	claim: string,
	mine: boolean,
};

export type Weight = "bold" | "normal" | "dim";

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

